// Готовим документы к загрузке. Текст уже собран в kb_chunks (SQL-скрипт),
// здесь только приводим форму и прокидываем kb_id в метаданные, чтобы найденный
// фрагмент можно было проследить обратно до строки Postgres.
const out = [];
for (const item of $input.all()) {
  const r = item.json;
  const meta = typeof r.metadata === 'string' ? JSON.parse(r.metadata) : (r.metadata || {});
  out.push({ json: {
    kb_id: r.id,
    text: r.content,
    meta: { ...meta, kb_id: r.id }
  }});
}
if (out.length === 0) {
  throw new Error(
    'Индексировать нечего: все чанки уже помечены как проиндексированные. ' +
    'Это защита от дублей — повторный прогон W5 больше не заливает базу второй раз. ' +
    'Если нужна ПЕРЕиндексация: пересоздайте коллекцию basilik_kb и выполните ' +
    'update kb_chunks set indexed_at = null;'
  );
}
return out;
